"""Discrete transforms, complete arithmetic, MATLAB and applications."""
from html import escape

MATLAB_CODE = '''N = 8;
k = (0:N-1).';
x = 2*pi*k/N;
f = sin(x) + sin(3*x);

w = exp(-1i*2*pi/N);
W = zeros(N,N);
for n = 0:N-1
    for j = 0:N-1
        W(n+1,j+1) = w^(n*j);
    end
end

X_matrix = W*f;                % Unnormalized forward DFT
X_fft = fft(f);                % Same normalization
f_recovered = conj(W)*X_matrix/N;
fprintf('DFT difference: %.3e\\n', norm(X_matrix-X_fft));
fprintf('Inverse error: %.3e\\n', norm(f_recovered-f));

bins = -N/2:N/2-1;
stem(bins, abs(fftshift(X_fft)), 'filled');
xlabel('Signed frequency index n');
ylabel('|X_n|');
grid on;'''

def populate(add, C, M, table):
    add(25, 'Discrete Fourier transform(이산 푸리에 변환)의 출발점', [
        C('함수 전체에서 N개의 표본으로', M(r"x_k=\frac{2\pi k}{N},\qquad f_k=f(x_k),\qquad k=0,\ldots,N-1"), '구간 [0,2π)에서 N개를 일정 간격으로 sampling(표본화)합니다. x=2π는 x=0과 같은 주기 위치이므로 중복 포함하지 않습니다. 이 값들을 정확히 통과하는 지수형 보간식 q를 구합니다.', M(r"q(x)=\sum_{n=0}^{N-1}c_ne^{inx},\qquad q(x_k)=f_k")),
        C('계수는 적분 대신 유한합', M(r"\boxed{c_n=\frac1N\sum_{k=0}^{N-1}f_ke^{-inx_k}=\frac1N\sum_{k=0}^{N-1}f_ke^{-2\pi ink/N}}"), '뒤의 행렬·FFT 예제는 정변환 합에서 1/N을 빼는 규약을 사용합니다. 혼동을 피하기 위해 cₙ은 정규화된 보간 계수, Xₙ=Ncₙ은 비정규화 DFT로 구분합니다. f를 유한 표본으로만 알 때 q=f가 모든 x에서 보장되는 것은 아닙니다.')
    ], [
        C('1 · 컴퓨터에는 함수식 대신 숫자 목록이 들어옵니다.', '센서가 일정 시간마다 측정한 값은 f₀, f₁, …처럼 유한 개의 숫자입니다. 무한히 많은 x에서 값을 아는 것이 아니므로 연속 적분을 그대로 계산할 수 없습니다. 표본 N개에서 주파수 성분 N개를 찾는 것이 discrete Fourier transform(이산 푸리에 변환), DFT입니다.'),
        C('2 · 한 바퀴를 N칸으로 나눕니다.', M(r"x_k=2\pi k/N,\qquad k=0,1,\ldots,N-1"), '예를 들어 N=4이면 위치는 0, π/2, π, 3π/2입니다. 2π는 다시 0으로 돌아온 같은 자리이므로 넣지 않습니다. k는 측정 위치의 번호이고, n은 찾아낼 파동의 번호입니다.'),
        C('3 · N개의 파동으로 N개의 값을 맞춥니다.', M(r"q(x)=c_0+c_1e^{ix}+\cdots+c_{N-1}e^{i(N-1)x},\qquad q(x_k)=f_k"), '미지수는 파동 크기 c₀부터 cₙ₋₁까지 N개입니다. 각 표본 위치에서 원래 숫자와 같아지게 정합니다. 표본 사이의 모양까지 유일하게 알아낸다는 뜻은 아닙니다. 표본점에서는 같은 값을 가지는 다른 함수가 얼마든지 있을 수 있습니다.'),
        C('4 · 왜 곱해서 더하면 계수가 나올까요?', M(r"c_n=\frac1N\sum_{k=0}^{N-1}f_ke^{-2\pi ink/N}"), '앞 단원에서 기준 파동을 곱해 적분하면 다른 파동이 상쇄되었습니다. 여기서는 정해진 N개 위치에서 곱해 더하면 다른 파동이 상쇄됩니다. 마지막 1/N은 같은 파동을 곱했을 때 남는 N을 나누는 것입니다. 다음 두 페이지에서 그 상쇄를 실제로 증명합니다.')
    ], audit='원본 계수식의 합 아래에는 n이 쓰여 있지만 실제로 훑는 표본 번호는 k입니다. 본문에서는 합 지표 k와 주파수 번호 n을 구분합니다. 유한 표본의 복원과 원래 연속함수 전체의 복원을 구분하여 q(xₖ)=fₖ를 명시합니다.')

    add(26, 'Discrete orthogonality(이산 직교성) · 원하는 번호 고르기', [
        C('m번째 파동을 선택해 곱한다', M(r"\begin{aligned}f_k&=\sum_{n=0}^{N-1}c_ne^{inx_k},\\\sum_{k=0}^{N-1}f_ke^{-imx_k}&=\sum_{n=0}^{N-1}c_n\underbrace{\sum_{k=0}^{N-1}e^{i(n-m)x_k}}_{S_{nm}}.\end{aligned}"), 'm은 현재 추출하려는 주파수 번호로 고정합니다. k는 모든 표본점을 순회하고, n은 원래 전개에 들어 있던 파동 번호를 순회합니다.'),
        C('같은 번호와 다른 번호', M(r"S_{nm}=\sum_{k=0}^{N-1}r^k,\qquad r=e^{2\pi i(n-m)/N}"), 'n=m이면 r=1이라 모든 항이 1이고 합은 N입니다. n≠m이며 n,m이 0부터 N−1 사이의 서로 다른 번호이면 r≠1입니다. 이 경우는 다음 페이지의 유한 등비급수로 계산합니다.')
    ], [
        C('1 · 많은 계수 중 하나만 남기고 싶습니다.', 'fₖ 안에는 모든 주파수 성분이 섞여 있습니다. 그중 m번째 계수만 알고 싶다고 정합니다. 그러면 반대 방향 파동 e⁻ⁱᵐˣᵏ를 곱해 표본 전체를 더합니다. m은 목표 번호이므로 계산 중에 바꾸지 않습니다.', M(r"\sum_{k=0}^{N-1}f_ke^{-imx_k}")),
        C('2 · 원래 전개를 대입하면 파동끼리 곱해집니다.', M(r"e^{inx_k}e^{-imx_k}=e^{i(n-m)x_k}"), '서로 같은 번호 n=m이면 지수가 0이므로 모든 표본에서 1입니다. 그 경우 계수 cₘ은 없어지지 않고 N번 더해집니다. 다른 번호의 합이 0이 되는지만 확인하면 목표 계수를 고를 수 있습니다.'),
        C('3 · 표본 위치를 넣으면 등비수열이 됩니다.', M(r"e^{i(n-m)x_k}=\left(e^{2\pi i(n-m)/N}\right)^k=r^k"), 'k가 0,1,2,…로 늘 때마다 같은 복소수 r을 한 번씩 더 곱하므로 1,r,r²,…의 geometric progression(등비수열)입니다. 복소수라고 해서 새로운 합 공식을 쓰는 것이 아니라 고등학교의 유한 등비급수 공식을 그대로 쓸 수 있습니다.'),
        C('4 · N=4, n−m=1로 직접 확인합니다.', M(r"r=e^{i\pi/2}=i,\qquad1+i+i^2+i^3=1+i-1-i=0"), '실수 방향의 1과 −1, 허수 방향의 i와 −i가 각각 상쇄됩니다. 다음 페이지는 이 예시가 일반 N에서도 성립한다는 계산입니다.')
    ])

    add(27, '등비급수로 DFT 계수 공식 증명하기', [
        C('서로 다른 번호의 합은 0', M(r"S=1+r+\cdots+r^{N-1},\qquad(1-r)S=1-r^N"), M(r"r^N=e^{2\pi i(n-m)}=1\quad\Longrightarrow\quad S=\frac{1-r^N}{1-r}=0\quad(r\ne1)"), 'r=1인 경우에는 분모가 0이므로 이 식을 적용하지 않고 S=N으로 따로 계산합니다. 일반적으로 n−m이 N의 배수면 같은 표본 파동입니다.'),
        C('직교성을 대입해 계수를 추출', M(r"\sum_{k=0}^{N-1}e^{2\pi i(n-m)k/N}=\begin{cases}N,&n\equiv m\pmod N,\\0,&n\not\equiv m\pmod N,\end{cases}"), M(r"\sum_{k=0}^{N-1}f_ke^{-imx_k}=Nc_m\quad\Longrightarrow\quad c_m=\frac1N\sum_{k=0}^{N-1}f_ke^{-imx_k}"), 'n과 n+N의 표본값은 같으므로 N개보다 많은 주파수 번호는 중복됩니다. 이것이 aliasing(에일리어싱)의 기초 구조입니다. 표본 사이의 실제 주파수를 구분하려면 별도의 대역 제한과 표본화 조건이 필요합니다.')
    ], [
        C('1 · 등비급수 공식을 직접 만들어 봅니다.', M(r"\begin{aligned}S&=1+r+r^2+\cdots+r^{N-1},\\rS&=r+r^2+\cdots+r^{N-1}+r^N,\\S-rS&=1-r^N.\end{aligned}"), '두 줄을 빼면 가운데 항이 모두 사라집니다. r≠1일 때 양변을 1−r로 나누면 S=(1−rᴺ)/(1−r)입니다. 이 과정에는 실수라는 조건이 없으므로 복소수에도 그대로 적용됩니다.'),
        C('2 · 한 바퀴의 정수배는 원래 위치입니다.', M(r"r^N=e^{2\pi i(n-m)}=1"), 'n−m은 정수이므로 복소평면에서 정수 바퀴를 돌면 1로 돌아옵니다. 분자는 1−1=0입니다. n과 m이 서로 다른 N개 대표 번호이면 분모는 0이 아니므로 합은 0입니다.'),
        C('3 · 같은 번호일 때는 N이 남습니다.', 'n=m이면 r=1이라 애초의 합은 1을 N번 더한 것입니다. 이때 0/0인 등비급수 식을 사용하지 않습니다. 따라서 목표 번호만 N배로 남고 다른 번호는 모두 사라집니다.', M(r"\sum_{k=0}^{N-1}f_ke^{-imx_k}=Nc_m,\qquad\boxed{c_m=\frac1N\sum_{k=0}^{N-1}f_ke^{-imx_k}}")),
        C('4 · 왜 N개의 번호만 쓰나요?', M(r"e^{i(n+N)x_k}=e^{inx_k}e^{i2\pi k}=e^{inx_k}"), 'n과 n+N은 표본점에서 완전히 같은 파동입니다. 컴퓨터는 그 표본만 보고 둘 중 어떤 연속 파동이 실제였는지 구별할 수 없습니다. 이것이 aliasing(에일리어싱)입니다. DFT가 데이터에 없던 정보를 만들어 주는 것은 아닙니다.')
    ], audit='원본 등비급수 유도의 rᴺ 및 합 지표에 남아 있는 k·n 혼용을 정리했습니다. n=m일 때 N, 서로 다른 대표 번호일 때 0이라는 경우를 분리하고 r=1에 등비급수 분모 공식을 적용하지 않습니다.')

    add(28, 'DFT 행렬과 [0, 1, 4, 9]의 직접 계산', [
        C('원본의 정규화 혼용을 구분한다', M(r"X_n=\sum_{k=0}^{N-1}f_ke^{-2\pi ink/N}=Nc_n,\qquad f_k=\frac1N\sum_{n=0}^{N-1}X_ne^{2\pi ink/N}"), '앞의 cₙ은 1/N이 붙는 계수입니다. 이 페이지의 원본 행렬·예제·뒤의 FFT는 1/N이 없는 Xₙ을 사용합니다. 두 규약을 분리하면 어느 숫자가 맞는지 명확해집니다.'),
        C('N=4의 변환 행렬', M(r"w=e^{-2\pi i/4}=-i,\qquad\begin{pmatrix}X_0\\X_1\\X_2\\X_3\end{pmatrix}=\begin{pmatrix}1&1&1&1\\1&-i&-1&i\\1&-1&1&-1\\1&i&-1&-i\end{pmatrix}\begin{pmatrix}0\\1\\4\\9\end{pmatrix}"), M(r"\begin{aligned}X_0&=0+1+4+9=14,\\X_1&=0-i-4+9i=-4+8i,\\X_2&=0-1+4-9=-6,\\X_3&=0+i-4-9i=-4-8i.\end{aligned}")),
        C('앞 페이지의 계수와 역변환 확인', M(r"(c_0,c_1,c_2,c_3)=\frac14(X_0,X_1,X_2,X_3)=\left(\frac72,-1+2i,-\frac32,-1-2i\right)"), M(r"f_0=\frac14[14+(-4+8i)-6+(-4-8i)]=0"), 'X₀는 표본의 합 14, c₀는 평균 3.5입니다. Fourier matrix(푸리에 행렬)를 W라 하면 W의 켤레전치와 W의 곱이 NI이고, 여기의 W는 대칭이므로 역행렬은 (1/N)conj(W)로도 쓸 수 있습니다.')
    ], [
        C('1 · 같은 기호에 다른 배율을 섞지 않습니다.', '앞에서는 합을 N으로 나눈 cₙ을 구했습니다. 원본의 숫자 예제는 N으로 나누지 않은 합을 사용합니다. 그래서 여기서는 그 값을 Xₙ이라고 따로 부릅니다. 둘은 Xₙ=Ncₙ 관계입니다.', M(r"X_n=\sum_{k=0}^{N-1}f_kw^{nk},\qquad w=e^{-2\pi i/N},\qquad c_n=X_n/N")),
        C('2 · N=4이면 복소수 곱셈도 단순해집니다.', M(r"w=-i,\qquad w^0=1,\quad w^1=-i,\quad w^2=-1,\quad w^3=i,\quad w^4=1"), '4번 곱하면 다시 1이 됩니다. 행렬의 첫째 행은 주파수 0이라 모두 1입니다. 둘째 행은 1,−i,−1,i이고, 각 표본 0,1,4,9에 이 값을 순서대로 곱합니다.'),
        C('3 · 네 주파수를 한 줄씩 계산합니다.', M(r"\begin{aligned}X_0&=0\cdot1+1\cdot1+4\cdot1+9\cdot1=14,\\X_1&=0\cdot1+1(-i)+4(-1)+9i=-4+8i,\\X_2&=0\cdot1+1(-1)+4\cdot1+9(-1)=-6,\\X_3&=0\cdot1+1i+4(-1)+9(-i)=-4-8i.\end{aligned}"), '실수 부분끼리, i가 붙은 부분끼리 모았습니다. X₁과 X₃가 켤레인 것은 입력 표본이 모두 실수이기 때문입니다. 마지막 숫자만 외우기보다 이 네 줄에서 부호를 확인하십시오.'),
        C('4 · 평균을 묻는다면 14가 아니라 3.5입니다.', M(r"c_0=X_0/4=14/4=3.5,\qquad c=(3.5,\ -1+2i,\ -1.5,\ -1-2i)"), '비정규화 DFT의 0번 값 X₀는 전체 합입니다. 평균은 N으로 나누어야 합니다. 원본의 상단 공식처럼 1/N을 붙여 계산한다면 결과도 이 c값이어야 합니다.'),
        C('5 · 되돌릴 때는 지수 부호를 바꾸고 4로 나눕니다.', M(r"f_k=\frac14\sum_{n=0}^3X_ne^{2\pi ink/4}"), 'k=0이면 모든 파동이 1이라 X 네 값을 그냥 더한 뒤 4로 나눕니다. 합이 0이므로 첫 표본 0이 복원됩니다. 나머지 k에서도 같은 방법으로 1,4,9가 되돌아옵니다. 이 왕복 확인이 행렬 부호와 배율을 검사합니다.')
    ], role='예제·완성 풀이', audit='원본 상단에는 정변환에 1/N이 있지만 아래 행렬과 계산 결과는 1/N 없는 규약입니다. X=[14,−4+8i,−6,−4−8i], c=X/4를 모두 제시하고, 이후 FFT에는 X 규약을 사용합니다.')

    add(29, 'Fast Fourier transform(고속 푸리에 변환)의 원리', [
        C('DFT를 계산하는 효율적인 알고리즘', 'FFT는 다른 변환이 아니라 같은 DFT를 적은 연산으로 계산하는 방법입니다. 원본은 radix-2(기수 2) 방식으로 N=2ᵐ, M=N/2를 가정합니다. 직접 계산은 대략 N², 재귀적으로 분할하면 Nlog₂N에 비례하는 연산이 필요합니다.'),
        C('짝수 표본과 홀수 표본으로 분할', M(r"\begin{aligned}X_n&=\sum_{k=0}^{N-1}f_kw_N^{nk}\\&=\sum_{j=0}^{M-1}f_{2j}(w_N^2)^{nj}+w_N^n\sum_{j=0}^{M-1}f_{2j+1}(w_N^2)^{nj}\\&=E_n+w_N^nO_n,\qquad w_N=e^{-2\pi i/N},\quad w_N^2=w_M.\end{aligned}"), 'E,O는 각각 길이 M의 DFT입니다. 여기서 even/odd는 함수의 짝·홀 대칭이 아니라 표본 번호 0,2,…와 1,3,…를 뜻합니다.'),
        C('두 결과를 한 번에 얻는 butterfly(나비 연산)', M(r"\boxed{X_n=E_n+w_N^nO_n,\qquad X_{n+M}=E_n-w_N^nO_n\quad(0\le n<M)}"), 'E와 O는 번호에 대해 M주기이며 w_Nᴹ=−1입니다. 같은 중간 곱 w_NⁿOₙ을 더하고 빼서 출력 두 개를 얻습니다. 이를 N/2 크기 문제에 다시 반복하는 것이 재귀 분할입니다.')
    ], [
        C('1 · 답을 바꾸는 방법이 아니라 계산을 아끼는 방법입니다.', 'DFT는 출력 N개마다 입력 N개를 훑으므로 계산량이 대략 N×N입니다. FFT는 중복되는 계산을 공유합니다. 입력을 짝수 번호와 홀수 번호로 나눈 뒤 작은 DFT 두 개를 조합합니다. 목표는 여전히 똑같은 X입니다.'),
        C('2 · 표본의 “번호”를 나눕니다.', 'N=8이라면 짝수 번호 목록은 f₀,f₂,f₄,f₆이고 홀수 번호 목록은 f₁,f₃,f₅,f₇입니다. 표본값 자체가 짝수인지 홀수인지는 상관없습니다. 또 even function(짝함수), odd function(홀함수)이라는 함수 대칭과도 다릅니다.'),
        C('3 · 두 칸씩 건너뛰면 더 작은 DFT가 됩니다.', M(r"w_N^{n(2j)}=(w_N^2)^{nj}=w_M^{nj},\qquad w_N^{n(2j+1)}=w_N^n w_M^{nj}"), '짝수 번호는 2j로 써서 N점 파동의 두 칸 간격을 읽습니다. 그것은 M=N/2점 파동의 한 칸 간격과 같습니다. 홀수 번호는 2j+1이라 한 칸 더 이동한 인자 w_Nⁿ만 따로 붙습니다.', M(r"X_n=E_n+w_N^nO_n")),
        C('4 · 뒤쪽 절반의 출력은 빼기만 바뀝니다.', M(r"w_N^M=e^{-i\pi}=-1,\qquad X_{n+M}=E_n-w_N^nO_n"), '번호를 M만큼 늘리면 작은 DFT의 E와 O는 한 주기를 돌아 같은 값입니다. 추가 파동 인자만 −1배가 되므로 더하기가 빼기로 바뀝니다. 같은 중간값 하나로 앞쪽과 뒤쪽 출력을 동시에 얻는 구조가 butterfly(나비 연산)입니다.'),
        C('5 · 왜 Nlog₂N인가요?', 'N을 계속 절반으로 나누면 크기 1이 될 때까지 log₂N단계가 필요합니다. 각 단계에서 전체 표본 수에 비례하는 결합을 하므로 Nlog₂N 규모가 됩니다. N=8이면 8→4→2→1의 세 단계입니다. 정확한 연산 수는 구현에 따라 다르지만 직접 계산보다 증가 속도가 느려집니다.')
    ])

    add(30, 'FFT로 [0, 1, 4, 9] 다시 계산하기', [
        C('길이 2의 DFT 두 개', M(r"\begin{aligned}(f_0,f_2)&=(0,4)\quad\Longrightarrow\quad(E_0,E_1)=(0+4,0-4)=(4,-4),\\(f_1,f_3)&=(1,9)\quad\Longrightarrow\quad(O_0,O_1)=(1+9,1-9)=(10,-8).\end{aligned}"), '길이 2에서는 회전 인자가 −1이라 합과 차만 구하면 됩니다.'),
        C('회전 인자를 곱하고 두 출력을 결합', M(r"\begin{aligned}X_0&=E_0+w_4^0O_0=4+10=14,\\X_2&=E_0-w_4^0O_0=4-10=-6,\\X_1&=E_1+w_4^1O_1=-4+(-i)(-8)=-4+8i,\\X_3&=E_1-w_4^1O_1=-4-(-i)(-8)=-4-8i.\end{aligned}"), M(r"\boxed{X=(14,\,-4+8i,\,-6,\,-4-8i)}"), 'p.28의 행렬 계산과 동일합니다. 순서 0,2를 먼저 계산해도 최종 벡터는 주파수 번호 0,1,2,3 순서로 기록합니다.')
    ], [
        C('1 · 큰 행렬 대신 두 목록을 만듭니다.', '원래 입력은 [0,1,4,9]입니다. 짝수 번호 0과 2를 뽑으면 [0,4], 홀수 번호 1과 3을 뽑으면 [1,9]입니다. 이 분할에서 숫자의 위치를 잘못 옮기면 뒤 계산이 모두 달라집니다.'),
        C('2 · 두 숫자의 DFT는 합과 차입니다.', M(r"E=(0+4,0-4)=(4,-4),\qquad O=(1+9,1-9)=(10,-8)"), '각 쌍의 첫 성분은 낮은 주파수의 합이고, 둘째 성분은 부호가 번갈아 드는 차입니다. O₁은 1+9가 아니라 1−9=−8입니다. 바로 이 차가 원본 중간 줄과 최종 답의 일관성을 검사하는 지점입니다.'),
        C('3 · n=0은 그냥 더하고 뺍니다.', M(r"X_0=4+10=14,\qquad X_2=4-10=-6"), 'w⁰=1이라 별도 회전이 없습니다. E₀와 O₀를 한 번 더하고 한 번 빼서 출력 두 개를 얻었습니다.'),
        C('4 · n=1은 −i를 곱한 뒤 더하고 뺍니다.', M(r"(-i)O_1=(-i)(-8)=8i,\qquad X_1=-4+8i,\qquad X_3=-4-8i"), '두 음수를 곱하면 양수가 되어 8i입니다. X₃에서는 이 중간값 전체를 빼므로 −8i가 됩니다. 최종 순서대로 쓰면 [14,−4+8i,−6,−4−8i]이고, 직접 행렬로 구한 p.28의 답과 같습니다.'),
        C('5 · 계산법은 달라도 정규화는 그대로입니다.', '이 결과는 1/N을 붙이지 않은 X입니다. Fourier interpolation coefficient(푸리에 보간 계수) c가 필요하다면 마지막에 4로 나눕니다. FFT라는 알고리즘으로 바뀌었다고 1/N 규약이 저절로 바뀌지는 않습니다.')
    ], role='예제·완성 풀이', audit='원본 홀수 가지 입력 벡터의 표기가 짝수 가지와 중복되고, X₁·X₃ 중간 줄에는 f₁+f₃가 쓰여 있습니다. 홀수 가지는 [f₁,f₃], 해당 성분은 f₁−f₃=−8이어야 원본의 올바른 최종 답 −4±8i가 나옵니다.')

    add(31, 'MATLAB 예제 · sin x + sin 3x의 DFT', [
        C('표본과 예상 스펙트럼', M(r"N=8,\quad x_k=2\pi k/8,\quad f_k=\sin x_k+\sin(3x_k)"), M(r"X_1=X_3=-4i,\quad X_5=X_7=4i,\qquad X_0=X_2=X_4=X_6=0"), '지수 표현 sin(mx)=(eⁱᵐˣ−e⁻ⁱᵐˣ)/(2i)을 사용하면 양의 주파수 1,3에서 −Ni/2=−4i, 음의 주파수 −1,−3에서 +4i가 됩니다. N=8에서 음의 번호 −1,−3은 저장 번호 7,5에 해당합니다. 원본 그래프의 높이 4는 |Xₙ|입니다.'),
        C('원본 흐름을 완성한 실행 코드', '<pre><code class="language-matlab">'+escape(MATLAB_CODE)+'</code></pre>', '행렬 곱과 fft가 같은 비정규화 DFT를 구하는지, 역변환이 원래 표본을 돌려주는지 수치 오차로 확인합니다. fftshift는 그래프의 0주파수를 가운데로 옮기는 순서 재배열입니다. 새로운 변환을 수행하지 않습니다.'),
        C('진폭과 계수의 배율', '원래 사인 진폭은 각각 1입니다. 원시 DFT 크기 4를 진폭 4로 읽으면 안 됩니다. 정규화 계수의 양·음 주파수 크기는 |c|=|X|/N=1/2이고 두 성분이 한 실수 사인을 구성합니다. 이 예제의 양의 비영 주파수에서는 진폭 2|X|/N=1입니다. DC와 Nyquist 성분에는 이 두 배 규칙을 그대로 적용하지 않습니다.')
    ], [
        C('1 · 원래 신호에 들어 있는 파동을 이미 알고 있습니다.', 'f(x)=sin x+sin 3x이므로 한 바퀴에 한 번 흔들리는 성분과 세 번 흔들리는 성분이 있습니다. 둘 다 진폭은 1입니다. N=8개를 측정하고 DFT가 그 두 성분을 찾는지 확인하는 예제입니다.', M(r"f=(0,\sqrt2,0,\sqrt2,0,-\sqrt2,0,-\sqrt2)")),
        C('2 · 왜 막대가 두 개가 아니라 네 개인가요?', M(r"\sin(mx)=\frac{e^{imx}-e^{-imx}}{2i}=-\frac i2e^{imx}+\frac i2e^{-imx}"), '실수 사인 하나는 양의 주파수와 음의 주파수 두 복소 성분을 한 쌍으로 가집니다. 따라서 1과 3의 사인에는 +1,−1,+3,−3의 네 막대가 생깁니다. 음의 주파수는 추가로 다른 소리가 하나 더 있다는 뜻이 아니라 실수 파동을 복소수로 표현할 때 필요한 짝입니다.'),
        C('3 · 높이 4와 원래 진폭 1을 구분합니다.', M(r"c_1=c_3=-i/2,\quad c_{-1}=c_{-3}=i/2,\qquad X=Nc=8c"), 'c의 크기는 1/2이고 X는 그 8배이므로 |X|=4입니다. 프로그램 fft는 이 X 규약을 기본으로 사용합니다. 원래 사인의 진폭을 구하려면 양의 주파수에서 2|X|/N을 계산해 1로 되돌립니다.'),
        C('4 · 코드의 번호와 수학의 번호를 연결합니다.', '수학에서는 번호가 0부터 시작하지만 MATLAB 배열은 1부터 시작합니다. 그래서 W(n+1,j+1)에 w^(n*j)를 저장합니다. f는 세로 벡터로 만들고, W*f로 각 행의 가중합을 한 번에 계산합니다.', '<pre><code class="language-matlab">'+escape(MATLAB_CODE)+'</code></pre>'),
        C('5 · 그래프 위치를 바꾸는 이유', 'fft 결과는 번호 0,1,…,7 순서로 나옵니다. 끝의 5와 7은 부호 있는 주파수로 −3과 −1에 대응합니다. fftshift로 순서를 바꾸면 −4,−3,…,3 순서가 되어 0을 가운데 두고 그림을 볼 수 있습니다.', '위 코드의 DFT difference와 Inverse error는 부동소수점 반올림 수준의 작은 값이어야 합니다. 이론상 0인 성분이 아주 작은 숫자로 출력되는 것도 같은 수치 오차입니다. 아래 도구에서는 두 사인의 진폭을 바꾸며 원시 DFT 막대와 원래 파형을 함께 볼 수 있습니다.')
    ], role='계산 예제·코드 해설', audit='원본 코드는 f_hat, F_hat, Fhat를 혼용합니다. 실행 예제에서는 X_matrix와 X_fft로 구분하고 역변환에 실제 계산한 변수를 사용합니다. 부호 있는 주파수 축의 그림에는 abs와 fftshift 과정을 명시하여 높이 4의 의미를 설명합니다.')

    add(32, '응용 · Sound analysis(소리 분석)와 필터', [
        C('시간 파형에서 성분표로', '원본은 소리의 시간 파형을 주파수 성분으로 분리하고 일부 성분을 줄여 filtered signal(필터링된 신호)을 얻는 흐름을 보여 줍니다. FFT로 주파수를 분석하고, 목적에 맞는 응답 H를 곱한 뒤 역변환하면 시간 파형을 다시 얻습니다.', M(r"X_n=\operatorname{DFT}(x_k),\qquad Y_n=H_nX_n,\qquad y_k=\operatorname{IDFT}(Y_n)")),
        C('실제 주파수와 필터 해석', M(r"\Delta\nu=\frac{f_s}{N},\qquad \nu_n=\frac{nf_s}{N}\ \text{(양의 주파수 쪽)},\qquad\omega=2\pi\nu"), 'f_s는 초당 표본 수 Hz, N은 기록 표본 수입니다. 원본의 그림은 개념도이며 음원 데이터나 필터 사양은 제공되지 않았습니다. 높은 주파수라는 이유만으로 모두 잡음인 것은 아닙니다. 필요한 고조파까지 제거하면 음색도 변합니다. 실수 출력에는 양·음 주파수의 켤레 대칭을 보존해야 합니다.')
    ], [
        C('1 · 시간 그래프만 보면 섞인 소리를 구분하기 어렵습니다.', '마이크는 그 순간의 전체 압력 변화를 하나의 숫자로 측정합니다. 낮은 소리와 높은 소리가 섞이면 복잡한 파형이 됩니다. Fourier transform(푸리에 변환)은 각 반복 속도의 성분이 얼마나 큰지 보여 줍니다. 원본 가운데의 막대들은 그런 성분표를 그린 개념도입니다.'),
        C('2 · 필터는 주파수별 볼륨 조절입니다.', '원하는 대역에서는 H를 1에 가깝게, 줄이고 싶은 대역에서는 0에 가깝게 정합니다. 그리고 Y=HX로 각 성분의 크기와 위상을 조절합니다. 역변환을 하면 조절된 파동들을 다시 더한 시간 신호가 됩니다.', M(r"\text{측정값}\ \xrightarrow{\mathrm{DFT}}\ X\ \xrightarrow{\times H}\ Y\ \xrightarrow{\mathrm{IDFT}}\ \text{필터링한 측정값}")),
        C('3 · DFT 번호를 Hz로 바꾸려면 측정 간격이 필요합니다.', '편집자 예로 초당 8000번, 총 8000개를 측정했다면 1초 분량입니다. 주파수 한 칸은 8000/8000=1Hz이고 500번 칸은 500Hz에 해당합니다. 같은 초당 표본 수로 4000개만 측정하면 0.5초 분량이라 한 칸은 2Hz가 됩니다.', M(r"\Delta\nu=f_s/N=1/T,\qquad T=N/f_s")),
        C('4 · 큰 막대와 높은 막대가 곧 좋은 소리·잡음은 아닙니다.', '소리에는 기본음뿐 아니라 harmonic(고조파)도 들어 있으며 이것이 음색에 기여합니다. 높은 주파수를 모두 지우면 잡음뿐 아니라 필요한 성분도 줄어들 수 있습니다. 원본은 응용 개념을 보여 주며 구체적인 측정 자료는 없으므로, 어떤 막대가 실제 잡음인지 수치로 판정하지는 않습니다.')
    ], role='응용·편집자 보강')

    add(33, '응용 · Vibration analysis(진동 분석)', [
        C('가속도 신호의 주파수 성분을 해석한다', '원본은 accelerometer(가속도계)로 기계 진동을 측정하고, 스펙트럼의 주성분·고조파·추가 봉우리를 비교하는 흐름입니다. 운전 조건에 따른 기준 스펙트럼과 비교하면 불균형, 정렬 불량, 베어링 이상 등의 진단을 보조할 수 있습니다.'),
        C('가장 큰 봉우리와 고유진동수는 같은 말이 아니다', 'Dominant frequency(우세 주파수)는 측정 신호에서 큰 성분입니다. Natural frequency(고유진동수)는 질량·강성과 경계조건으로 정해지는 시스템의 특성입니다. 가진 주파수가 고유진동수 근처일 때 resonance(공진)으로 응답이 커질 수 있지만, 큰 봉우리 하나만으로 고유진동수나 고장 원인을 확정하지 않습니다.', M(r"\nu_{\mathrm{rot}}=\frac{\mathrm{rpm}}{60},\qquad\nu_n=n\nu_{\mathrm{rot}}"), '편집자 예로 3000rpm은 50Hz이며 100,150Hz는 그 2배·3배입니다. 원본 그래프의 50Hz 부근 주성분과 고조파를 읽는 예시일 뿐, 원본 장비의 실제 회전속도가 제공되었다는 뜻은 아닙니다.')
    ], [
        C('1 · 동역학에서 본 진동을 측정값으로 만납니다.', '기계가 떨리면 가속도계가 시간마다 가속도를 기록합니다. 눈으로 복잡한 흔들림만 보면 어떤 반복 성분이 강한지 알기 어렵습니다. DFT로 주파수별 크기를 보면 반복 속도를 분리해 볼 수 있습니다.'),
        C('2 · 회전속도는 초당 회전수로 바꿉니다.', 'rpm은 분당 회전수입니다. 한 분은 60초이므로 60으로 나누면 초당 회전수 Hz입니다. 편집자 예로 3000rpm이면 50Hz입니다. 한 회전마다 같은 힘이 생기면 50Hz 성분이, 한 회전 중 두 번 비슷한 변화가 생기면 100Hz 성분이 나타날 수 있습니다.', M(r"3000\ \mathrm{rpm}\div60=50\ \mathrm{Hz};\qquad2\times50=100\ \mathrm{Hz}")),
        C('3 · 가장 큰 성분이 기계의 고유진동수라고 바로 결론내리면 안 됩니다.', '그 주파수로 힘을 강하게 주고 있어서 클 수도 있고, 시스템이 그 주파수에 잘 반응해서 클 수도 있습니다. Natural frequency(고유진동수)는 시스템 자체의 특성이고, dominant frequency(우세 주파수)는 지금 측정한 데이터에서 큰 성분이라는 관찰입니다. 둘을 구분해야 동역학의 공진 개념과 올바르게 연결됩니다.'),
        C('4 · 이 단원에서 가져갈 분석 순서', '측정 간격으로 주파수 축을 정하고, DFT 크기와 필요한 위상을 계산한 뒤, 회전수·운전 조건·이전 정상 자료와 비교합니다. 원본 그림의 특정 봉우리를 실제 장비 고장으로 확정할 데이터는 없습니다. 여기서는 변환이 시간 신호에서 반복 성분을 드러내는 도구라는 역할을 익히면 됩니다.')
    ], role='응용·동역학 연결')
